ruleToc.chapterList:
@js:
function gp(h,k){var m=String(h).match(new RegExp(k+"\\s*=\\s*'([^']+)'"));return m?m[1]:'';}
function add(n,u){list.push(JSON.stringify({name:String(n),url:String(u)}));}
var list=[];
var html=String(result||src||'');
var id=gp(html,'AID'),sid=gp(html,'ASID')||'1',nid=gp(html,'ANID')||'1',tk=gp(html,'AK');
if(!id){var um=String(baseUrl).match(/\/v5\/(\d+)/);id=um?um[1]:'';}
var dm = String(baseUrl).match(/^(https?:\/\/[^\/]+)/);
var domain = dm ? dm[1] : String(source.getKey()).replace(/\/+$/,'');
if(!id||!tk){
  add('获取失败-页面里没找到AID/AK',baseUrl);
}else{
  var body='id='+id+'&sid='+sid+'&nid='+nid+'&tk='+tk+'&g=1&x=180&y=320&dt=1200&sw=1080&sh=1920&tz=-480&t='+Date.now();
  var text='';
  try{
    var headers={
      'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8',
      'X-Requested-With':'XMLHttpRequest',
      'Referer':String(baseUrl),
      'Origin':domain,
      'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
    };
    var resp=java.post(domain+'/static/count.php',body,headers);
    text=(resp&&typeof resp.body==='function')?String(resp.body()):String(resp);
    var j=JSON.parse(text);
    if(j&&j.ok&&j.u){
      add((book&&book.name)?book.name:'点击播放',java.base64Decode(j.u));
    }else{
      add('获取失败-接口无返回:'+text.substring(0,80),baseUrl);
    }
  }catch(e){
    add('获取失败:'+e+' '+text.substring(0,60),baseUrl);
  }
}
list;

